## 7. 홈 화면 연동 (`src/scenes/ModeSelectScene.ts`)

```typescript
// 기억 로그 버튼 추가 — createReleaseNotesLink 근처에 배치
private createStoryLogButton(x: number, y: number) {
  const { hasUnreadNewLogs } = await import('../utils/storyProgress');

  const text = this.add.text(x - 50, y, '📁 기억 로그', {
    fontSize: '14px',
    color: '#cccccc',
    stroke: '#000',
    strokeThickness: 3,
  }).setOrigin(0.5).setInteractive({ useHandCursor: true });

  text.on('pointerover', () => text.setColor('#FFD700'));
  text.on('pointerout',  () => text.setColor('#cccccc'));
  text.on('pointerdown', () => this.scene.start('StoryLogScene'));

  // 빨간 점 (새 로그 있을 때)
  if (hasUnreadNewLogs()) {
    this.add.circle(text.x + text.width / 2 + 6, text.y - 6, 4, 0xff4444)
      .setDepth(text.depth + 1);
  }
}

// create()에서 호출
create() {
  // ...기존 코드...
  this.createReleaseNotesLink(cx + 50, H - 80);   // 기존 위치 조정
  this.createStoryLogButton(cx - 50, H - 80);      // ← 추가
}
```

