## 8. 게임 이벤트 연동

각 수집/플레이 이벤트 발생 시 `recordEvent()` 호출.

```typescript
// GameScene.ts — 특수똥 수집 시
import { recordEvent } from '../utils/storyProgress';

private handleTopazCollected(poop: Phaser.Physics.Arcade.Sprite) {
  // ...기존 처리...
  recordEvent('topaz', 1);        // ← 추가
}

private handleGoldCollected(poop: Phaser.Physics.Arcade.Sprite) {
  // ...기존 처리...
  recordEvent('gold', 1);         // ← 추가
}

private handleDiamondCollected(poop: Phaser.Physics.Arcade.Sprite) {
  // ...기존 처리...
  recordEvent('diamond', 1);      // ← 추가
}

// 게임 오버 시 플레이 횟수 카운트
protected async showGameOverUI(isNewRecord: boolean) {
  recordEvent('playCount', 1);    // ← 추가
  // ...기존 처리...
}

// GachaScene.ts — 뽑기 완료 시
recordEvent('skor', cost);        // 사용한 SKOR만큼 누적
recordEvent('gacha', count);      // 뽑기 횟수 누적
```

