    if (topazPoop.body) {
      const fallSpeed = this.difficultyConfig.baseSpeed + (this.difficultyLevel * POOP_CONFIG.normal.speedIncrement) - POOP_CONFIG.topaz.speedReduction;
      topazPoop.body.velocity.y = fallSpeed;
    }
