  /**
   * 이니셜 입력 UI 표시
   */
  private showInitialInputUI() {
    const W = this.scale.width;
    const H = this.scale.height;
    const cx = W / 2;
    // 안내 텍스트
    this.add.text(cx, H / 2 - 50, '이니셜 입력 (영어 대문자 3자)', {
      fontSize: '18px',
      color: '#ffffff',
      fontStyle: 'bold',
      stroke: '#000000',
      strokeThickness: 3
    }).setOrigin(0.5).setDepth(200);

    // HTML input 엘리먼트 생성
    const inputElement = document.createElement('input');
    inputElement.type = 'text';
    inputElement.maxLength = 3;
    inputElement.placeholder = 'ABC';

    // 캔버스 실제 위치·스케일에 맞춰 input 좌표 계산
    // (Phaser FIT 스케일 모드에서 캔버스가 이동/축소될 수 있으므로 DOM 좌표계와 동기화)
    const canvas = this.game.canvas;
    const rect = canvas.getBoundingClientRect();
    const gameW = this.scale.width;
    const gameH = this.scale.height;
    const scaleX = rect.width / gameW;
    const scaleY = rect.height / gameH;
    // 게임 좌표 (cx, H/2-15) → viewport 픽셀 좌표로 변환
    const screenLeft = rect.left + (gameW / 2) * scaleX;
    const screenTop  = rect.top  + (gameH / 2 - 15) * scaleY;

    inputElement.style.cssText = `
      position: fixed;
      left: ${screenLeft}px;
      top: ${screenTop}px;
      transform: translateX(-50%);
      width: ${Math.round(130 * scaleX)}px;
      height: ${Math.round(44 * scaleY)}px;
      font-size: ${Math.round(22 * scaleY)}px;
      text-align: center;
      text-transform: uppercase;
      border: ${Math.max(2, Math.round(3 * scaleY))}px solid #FFD700;
      border-radius: 8px;
      background: #000;
      color: #fff;
      font-weight: bold;
      letter-spacing: ${Math.round(6 * scaleX)}px;
      outline: none;
      box-sizing: border-box;
      z-index: 9999;
    `;

    // 기존 이니셜이 있으면 미리 채우기
    const existingInitials = getUserInitials();
    if (existingInitials) {
      inputElement.value = existingInitials;
    }

    document.body.appendChild(inputElement);
    inputElement.focus();

    // 대문자만 입력되도록
    inputElement.addEventListener('input', (e) => {
      const target = e.target as HTMLInputElement;
      target.value = target.value.toUpperCase().replace(/[^A-Z]/g, '');
    });

    // 제출 버튼 텍스트
    const submitButtonText = this.add.text(cx, H / 2 + 75, '랭킹 등록', {
      fontSize: '24px',
      color: '#00ff00',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 4,
      padding: { x: 20, y: 10 }
    }).setOrigin(0.5).setInteractive().setDepth(200);

    // 에러 메시지 영역
    let errorText: Phaser.GameObjects.Text | null = null;

    // 제출 버튼 클릭
    submitButtonText.on('pointerdown', async () => {
      const initials = inputElement.value.trim().toUpperCase();

      // 검증
      if (initials.length !== 3) {
        if (errorText) errorText.destroy();
        errorText = this.add.text(cx, H / 2 + 120, '정확히 3글자를 입력하세요', {
          fontSize: '16px',
          color: '#ff0000',
          fontStyle: 'bold',
          stroke: '#000',
          strokeThickness: 3
        }).setOrigin(0.5).setDepth(200);
        return;
      }

      if (!/^[A-Z]{3}$/.test(initials)) {
        if (errorText) errorText.destroy();
        errorText = this.add.text(cx, H / 2 + 120, '영어 대문자만 입력하세요', {
          fontSize: '16px',
          color: '#ff0000',
          fontStyle: 'bold',
          stroke: '#000',
          strokeThickness: 3
        }).setOrigin(0.5).setDepth(200);
        return;
      }

      // 이니셜 저장
      setUserInitials(initials);

      // input 제거
      document.body.removeChild(inputElement);
      submitButtonText.destroy();
      if (errorText) errorText.destroy();

      // 랭킹 제출
      const submittingText = this.add.text(cx, H / 2, '랭킹 제출 중...', {
        fontSize: '18px',
        color: '#ffff00',
        fontStyle: 'bold',
        stroke: '#000',
        strokeThickness: 3
      }).setOrigin(0.5).setDepth(200);

      try {
        // 캐릭터 타입 결정 (이미 init()에서 검증된 값 사용)
        const characterType = this.selectedCharId;

        // 세션이 완료될 때까지 대기 (대부분 이미 완료되어 있음)
        const sessionId = await this.sessionPromise;

        const result = await submitScore(
          this.score,
          this.scoreDifficulty,
          initials,
          {
            gameStartTime: this.gameStartTime,
            gameEndTime: realNow(),
            goldCollected: this.goldCollected,
            diamondCollected: this.diamondCollected,
            topazCollected: this.topazCollected,
            rainbowCollected: this.rainbowCollected,
            collectBonusTotal: this.collectBonusTotal,
            abilityBonusTotal: this.abilityBonusTotal,
          },
          characterType,
          sessionId
        );

        submittingText.destroy();

        // 순위 표시
        if (result.rank !== null) {
          this.add.text(cx, H / 2 + 40, `🏆 전체 ${result.rank}위! 🏆`, {
            fontSize: '24px',
            color: '#FFD700',
            fontStyle: 'bold',
            stroke: '#000',
            strokeThickness: 3,
            padding: { top: 4 },
          }).setOrigin(0.5).setDepth(200);
        }

        // 이니셜 표시
        this.add.text(cx, H / 2 + 80, `${initials}`, {
          fontSize: '20px',
          color: '#00ff00',
          fontStyle: 'bold',
          stroke: '#000',
          strokeThickness: 3,
          letterSpacing: 4
        }).setOrigin(0.5).setDepth(200);

      } catch (error) {
        console.error('Failed to submit score:', error);
        submittingText.setText('❌ 랭킹 제출 실패');
        submittingText.setColor('#ff0000');
      }

      // 재시작 버튼 표시
      this.showRestartButton(true);
    });

    // Enter 키로도 제출 가능
    inputElement.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        submitButtonText.emit('pointerdown');
      }
    });
  }

  // 서버 getBracketCap과 동일 — 낙관적 UI 계산용 (서버 응답 전 예상값 표시)
  private getSkorBracketCap(score: number): number {
    if (score < 500)  return 20;
    if (score < 1000) return 45;
    if (score < 1500) return 80;
    if (score < 2000) return 115;
    if (score < 3000) return 160;
    if (score < 5000) return 215;
    return 280;
  }

  /**
   * 게임오버 시 SKOR 정제 수익 제출 및 화면 표시
   */
  private async submitSkorOnGameOver(statusText: Phaser.GameObjects.Text) {
    // ── 낙관적 UI: 서버 응답 전에 예상 SKOR 즉시 계산 ──
    const rawSkor =
      this.goldCollected * 0.5 +
      this.diamondCollected * 1.5 +
      this.topazCollected * 3.5 +
      this.rainbowCollected * 10.0;
    const estimatedSkor = Math.floor(Math.min(rawSkor, this.getSkorBracketCap(this.score)));

    // floor 후 0이면 API 호출 없이 즉시 종료 (퀘스트 진행도도 없음)
    if (estimatedSkor <= 0) {
      statusText.setText('💰 +0 SKOR (아이템 없음)');
      statusText.setColor('#888888');
      return;
    }

    statusText.setText(`💰 +${estimatedSkor} SKOR 획득!`);
    statusText.setColor('#FFD700');

    // ── 백그라운드 API 호출: 실제 결과로 보정 ──
    try {
      const result: SkorSubmitResponse = await submitSkor({
        score: this.score,
        goldCollected: this.goldCollected,
        diamondCollected: this.diamondCollected,
        topazCollected: this.topazCollected,
        rainbowCollected: this.rainbowCollected,
      });

      if (!this.scene.isActive()) return;

      // 주간 캡 소진 또는 실제값이 예상과 다른 경우만 갱신
      if (result.weeklyCapRemaining <= 0 && result.totalSkorAdded === 0) {
        statusText.setText(`💰 주간 한도 도달 (SKOR 없음)`);
        statusText.setColor('#888888');
      } else if (result.totalSkorAdded !== estimatedSkor) {
        statusText.setText(`💰 +${result.totalSkorAdded} SKOR 획득!`);
      }

      // 퀘스트 달성 시 추가 알림 (항상 표시)
      if (result.questRewards.length > 0) {
        const questLabels: Record<string, string> = {
          gold: '금똥', diamond: '다이아', topaz: '토파즈', rainbow: '무지개',
        };
        const questText = result.questRewards
          .map(r => `${questLabels[r.quest] ?? r.quest} 퀘스트 +${r.reward}`)
          .join(' / ');
        this.add.text(this.scale.width / 2, statusText.y + 23, `🎯 ${questText}`, {
          fontSize: '13px',
          color: '#88ff88',
          stroke: '#000',
          strokeThickness: 2,
          padding: { top: 3 },
        }).setOrigin(0.5).setDepth(200);
      }
    } catch {
      // 실패해도 낙관적으로 보여준 숫자 유지 (정제 결과는 서버에서 처리됨)
    }
  }

  /**
   * 재시작 버튼 표시 (다시 하기 + 메인 메뉴) - 버튼 스타일
   * @param isNewRecord 새 기록 달성 여부 (SKOR 텍스트 위치에 따라 버튼 y 조정)
   */
  private showRestartButton(isNewRecord = false) {
    const W = this.scale.width;
    const H = this.scale.height;
    const cx = W / 2;
    // 새 기록 시: SKOR 텍스트(H/2+118) + 퀘스트(+23) 아래 배치
    // 일반 시: SKOR 텍스트(H/2+80) + 퀘스트(+23) 아래 배치
    const retryY = isNewRecord ? H / 2 + 170 : H / 2 + 155;
    const menuY  = isNewRecord ? H / 2 + 248 : H / 2 + 235;

    // 다시 하기 버튼 배경
    const retryButtonBg = this.add.rectangle(cx, retryY, 250, 70, 0x00aa00)
      .setOrigin(0.5)
      .setDepth(199)
      .setStrokeStyle(3, 0xffffff);

    // 다시 하기 버튼 텍스트
    const retryButtonText = this.add.text(cx, retryY, '다시 하기', {
      fontSize: '22px',
      color: '#ffffff',
      fontStyle: 'bold'
    }).setOrigin(0.5).setDepth(200);

    // 다시 하기 버튼 인터랙티브 영역 (배경을 클릭 가능하게)
    retryButtonBg.setInteractive({ useHandCursor: true });

    // 메인 메뉴 버튼 배경
    const menuButtonBg = this.add.rectangle(cx, menuY, 250, 70, 0x555555)
      .setOrigin(0.5)
      .setDepth(199)
      .setStrokeStyle(3, 0xffffff);

    // 메인 메뉴 버튼 텍스트
    const menuButtonText = this.add.text(cx, menuY, '메인 메뉴', {
      fontSize: '22px',
      color: '#ffffff',
      fontStyle: 'bold'
    }).setOrigin(0.5).setDepth(200);

    // 메인 메뉴 버튼 인터랙티브 영역
    menuButtonBg.setInteractive({ useHandCursor: true });

    // 호버 효과 - 다시 하기 버튼
    retryButtonBg.on('pointerover', () => {
      retryButtonBg.setFillStyle(0x00ff00);
      retryButtonBg.setScale(1.05);
      retryButtonText.setScale(1.05);
    });
    retryButtonBg.on('pointerout', () => {
      retryButtonBg.setFillStyle(0x00aa00);
      retryButtonBg.setScale(1);
      retryButtonText.setScale(1);
    });

    // 호버 효과 - 메인 메뉴 버튼
    menuButtonBg.on('pointerover', () => {
      menuButtonBg.setFillStyle(0x777777);
      menuButtonBg.setScale(1.05);
      menuButtonText.setScale(1.05);
    });
    menuButtonBg.on('pointerout', () => {
      menuButtonBg.setFillStyle(0x555555);
      menuButtonBg.setScale(1);
      menuButtonText.setScale(1);
    });

    retryButtonBg.on('pointerdown', () => {
      const existingInput = document.querySelector('input');
      if (existingInput) document.body.removeChild(existingInput);
      this.sound.stopAll();
      if (this.player) this.player.cleanupEffects();
      this.scene.restart({ gameMode: this.gameMode, difficulty: this.difficulty, purePhysical: this.purePhysical });
    });

    menuButtonBg.on('pointerdown', () => {
      const existingInput = document.querySelector('input');
      if (existingInput) document.body.removeChild(existingInput);
      this.sound.stopAll();
      if (this.player) this.player.cleanupEffects();
      this.scene.start('ModeSelectScene');
    });
  }
}

import type Phaser from 'phaser';
import { GameMode, GAME_MODES, type GameModeConfig } from '../types/GameMode';
import { getSkorBalance, getCachedSkorBalance, cacheSkorBalance } from '../utils/skor';
import { setBgmMuted } from '../utils/settings';
import { hasUnreadNewLogs } from '../utils/storyProgress';
import BaseScene from './BaseScene';

export default class ModeSelectScene extends BaseScene {
  private skorText!: Phaser.GameObjects.Text;
  private settingsPanel: Phaser.GameObjects.Container | null = null;

  constructor() {
    super('ModeSelectScene');
  }

  preload() {
    if (!this.textures.exists('background2')) {
      this.load.image('background2', 'assets/backgrounds/background2.webp');
    }
    if (!this.textures.exists('title')) {
      this.load.image('title', 'assets/title.webp');
    }
  }

  create() {
    super.create();

    const W = this.scale.width;
    const H = this.scale.height;
    const cx = W / 2;
    const yOff = (H - 600) / 2;

    const background = this.add.image(cx, H / 2, 'background2');
    background.setDisplaySize(W, H);

    const title = this.add.image(cx, 90 + yOff, 'title');
    title.setScale(0.4);

    this.add.text(cx, 190 + yOff, '모드를 선택하세요', {
      fontSize: '20px',
      color: '#fff',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 4
    }).setOrigin(0.5);

    // 클래식 + 대전 모드 버튼 (같은 줄, 캐릭터/랭킹 버튼과 동일 크기)
    this.createModeButton(GAME_MODES[0], cx - 80, 250 + yOff);
    this.createBattleButton(cx + 80, 250 + yOff);

    // 뽑기 버튼 (SKOR 잔액 포함)
    this.createGachaButton(cx, 345 + yOff);

    // 하단 버튼 행: 캐릭터 선택 + 랭킹
    this.createCharacterButton(cx - 80, 435 + yOff);
    this.createLeaderboardButton(cx + 80, 435 + yOff);

    // 기억 로그 버튼
    this.createStoryLogButton(cx, 520 + yOff);

    // 릴리즈 노트 링크
    this.createReleaseNotesLink(cx, H - 80);

    // 설정 버튼 (우하단)
    this.createSettingsButton(W - 26, H - 26);

    // SKOR 잔액 비동기 로드
    this.loadSkorBalance();
  }

  private async loadSkorBalance() {
    try {
      const balance = await getSkorBalance();
      cacheSkorBalance(balance);
      if (this.skorText?.active) {
        this.skorText.setText(`💰 ${Math.floor(balance)} SKOR`);
      }
    } catch {
      // 잔액 로드 실패 시 캐시 값 유지
    }
  }

  private createModeButton(modeConfig: GameModeConfig, x: number, y: number) {
    const button = this.add.rectangle(x, y, 140, 70, 0xffffff, 1);
    button.setStrokeStyle(3, 0x000000);

    const titleText = this.add.text(x, y, modeConfig.name, {
      fontSize: '18px',
      color: '#000',
      fontStyle: 'bold'
    }).setOrigin(0.5);

    button.setInteractive({ useHandCursor: true });
    titleText.setInteractive({ useHandCursor: true });

    [button, titleText].forEach(element => {
      element.on('pointerover', () => button.setFillStyle(0xffff99));
